(window.ArduinoSketches=window.ArduinoSketches||{})["b3_03_toggle_buggy"]={"ok":true,"flash":932,"ram":10,"program":"","name":"b3_03_toggle_buggy","source":"// ==================================================================\n//   BAND 3, PART 8  -  THIS ONE DOES NOT WORK PROPERLY\n//\n//   WHAT IT SHOULD DO\n//     Press once, light on. Press again, light off.\n//\n//   WHAT IT ACTUALLY DOES\n//     Goes DIM while you hold the button, because it flips far\n//     faster than your eye can follow, then lands on\n//     whichever state it happened to be in. Useless.\n//\n//     The logic is correct. Nothing is misspelled. Work out why\n//     before you look at the fixed version.\n//\n//     Hint: how many times a second does loop run?\n//\n//     Band 3 Part 9 explains it.\n//\n//   WIRING\n//     Same as b3_01.\n// ==================================================================\n\nint buttonPin = 2;\nint ledPin = 8;\n\nbool lightIsOn = false;\n\nvoid setup() {\n  pinMode(buttonPin, INPUT_PULLUP);\n  pinMode(ledPin, OUTPUT);\n}\n\nvoid loop() {\n  if (digitalRead(buttonPin) == LOW) {\n\n    if (lightIsOn == true) {\n      lightIsOn = false;\n    } else {\n      lightIsOn = true;\n    }\n\n  }\n\n  if (lightIsOn == true) {\n    digitalWrite(ledPin, HIGH);\n  } else {\n    digitalWrite(ledPin, LOW);\n  }\n}\n","compiler":"arduino-cli 1.5.1, arduino:avr:uno"};
